    public Xbf54 processPayment(Xdg64 order, Xrd81 user, Xbf54RequestDto requestDto) {
        Instant start = Instant.now();
        try {
            validatePaymentRequest(order, user, requestDto);

            log.info("결제 처리 시작: 주문ID={}, 사용자={}, 결제유형={}",
                    order.getId(), user.getEmail(), requestDto.getResolvedPaymentType());

            Xbf54 payment;

            switch (requestDto.getResolvedPaymentType()) {
                case "CARD":
                    payment = createCardPayment(order, user, (Xqg94RequestDto) requestDto);
                    break;
                case "ACCOUNT":
                    payment = createAccountPayment(order, user, (Xkg34RequestDto) requestDto);
                    break;
                case "GENERAL":
                    payment = createGeneralPayment(order, user, (Xjt86RequestDto) requestDto);
                    break;
                default:
                    throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_VALIDATION_FAILED,
                            "유효하지 않은 결제 유형: " + requestDto.getPaymentType());
            }


            notifyUsersAndUpdateSaleStatus(order, payment);

            log.info("결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), payment.getId(), payment.getStatus());

            return payment;
        } catch (Xbf54Exception e) {
            log.error("결제 처리 실패: 주문ID={}, 사용자={}, 에러코드={}, 메시지={}",
                    order != null ? order.getId() : "null",
                    user != null ? user.getEmail() : "null",
                    e.getErrorCode().getCode(), e.getMessage());
            throw e;
        } catch (Exception e) {
            log.error("결제 처리 중 예상치 못한 오류 발생: 주문ID={}, 사용자={}, 오류={}",
                    order != null ? order.getId() : "null",
                    user != null ? user.getEmail() : "null",
                    e.getMessage(), e);
            throw new Xdf64Exception("결제 처리 중 오류가 발생했습니다: " + e.getMessage());
        } finally {

            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("결제 처리 총 소요 시간: {}ms", duration.toMillis());
        }
    }









    private void validatePaymentRequest(Xdg64 order, Xrd81 user, Xbf54RequestDto requestDto) {
        if (order == null) {
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_PROCESSING_FAILED, "주문 정보가 없습니다.");
        }

        if (user == null) {
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_PROCESSING_FAILED, "사용자 정보가 없습니다.");
        }

        if (requestDto == null) {
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_VALIDATION_FAILED, "결제 요청 정보가 없습니다.");
        }


        if (!order.getId().equals(requestDto.getOrderId())) {
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_VALIDATION_FAILED,
                    "주문 ID가 일치하지 않습니다. 요청ID: " + requestDto.getOrderId() + ", 실제ID: " + order.getId());
        }

        if (!user.getEmail().equals(requestDto.getUserEmail())) {
            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_VALIDATION_FAILED,
                    "사용자 이메일이 일치하지 않습니다. 요청이메일: " + requestDto.getUserEmail() + ", 실제이메일: " + user.getEmail());
        }


        if (requestDto.getPaidAmount() <= 0) {
            throw new Xbf54Exception(Xbf54ErrorCode.INVALID_PAYMENT_AMOUNT,
                    "결제 금액은 0보다 커야 합니다. 금액: " + requestDto.getPaidAmount());
        }
    }










    private Xbf54 createCardPayment(Xdg64 order, Xrd81 user, Xqg94RequestDto requestDto) {
        Instant start = Instant.now();
        try {
            log.info("카드 결제 처리 시작: 주문ID={}, 결제정보ID={}",
                    order.getId(), requestDto.getPaymentInfoId());


            Xbf54Info paymentInfo;
            try {
                paymentInfo = paymentInfoQueryService.getPaymentInfoEntity(user.getEmail(), requestDto.getPaymentInfoId());
                if (paymentInfo == null) {
                    throw new Xjs44Exception("결제 정보 ID: " + requestDto.getPaymentInfoId() + "를 찾을 수 없습니다.");
                }
            } catch (Xbf54Exception e) {
                throw e;
            } catch (Exception e) {
                throw new Xjs44Exception("결제 정보 조회 중 오류가 발생했습니다.", e);
            }


            Map<String, Object> response;
            try {
                response = portOneApiClient.processCardPayment(paymentInfo, requestDto.getPaidAmount());
            } catch (Xbf54Exception e) {
                throw e;
            } catch (Exception e) {
                throw new Xbf54ApiException("카드 결제 요청 중 오류가 발생했습니다: " + e.getMessage());
            }


            Xqg94 cardPayment = Xqg94.builder()
                    .cardNumber(paymentInfo.getCardNumber())
